"""GraphQL documents used by the CA account-creation flow."""

# Submits the account. Called twice: once to initiate, once with the SMS code.
SIGN_UP = "mutation SignUp($input:SignUpInput!){signUp(input:$input){auth{...AuthFragment}authCode{authCode cid}errors{...ErrorFragment}generateOtpResult{...OtpResultFragment}isMandatory2FASetupRequired twoFALoginOptions{...TwoFALoginOptionsFragment}}}fragment AuthFragment on AuthResult{loginId loginIdType emailId phoneNumber{number countryCode}authCode identityToken}fragment ErrorFragment on IdentitySignUpError{code message}fragment OtpResultFragment on GenerateOTPResult{receiptId otpOperation otpType otherAccountsWithPhone action{alternateOption currentOption nextFactor}}fragment TwoFALoginOptionsFragment on TwoFALoginOptions{twoFALoginMethods{method isConfigured precedence identity{phoneNumber{number countryCode isoCountryCode}formattedMaskedPhoneNumber emailId maskedEmailId}}}"

GET_LOGIN_OPTIONS = "query GetLoginOptions($input:UserOptionsInput!){getLoginOptions(input:$input){loginOptions{...LoginOptionsFragment}canUseEmailOTP phoneCollectionRequired authCode errors{...LoginOptionsErrorFragment}}}fragment LoginOptionsFragment on LoginOptions{loginId loginIdType emailId phoneNumber{number countryCode isoCountryCode}canUsePassword canUsePhoneOTP canUseEmailOTP loginPhoneLastFour maskedPhoneNumberDetails{loginPhoneLastFour countryCode isoCountryCode}loginMaskedEmailId signInPreference loginPreference lastLoginPreference hasRemainingFactors isPhoneConnected otherAccountsWithPhone loginMaskedEmailId hasPasskeyOnProfile accountDomain residencyRegion{residencyCountryCode residencyRegionCode}isIdentityMergeRequired requiresTokenBasedPasswordSetup}fragment LoginOptionsErrorFragment on IdentityLoginOptionsError{code message version}"

GENERATE_OTP = "mutation GenerateOtp($input:GenerateOTPInput!){generateOTP(input:$input){errors{...GenerateOtpErrorFragment}otpResult{...GenerateOtpResultFragment}}}fragment GenerateOtpErrorFragment on IdentityGenerateOTPError{code message}fragment GenerateOtpResultFragment on GenerateOTPResult{receiptId otpOperation otpType otherAccountsWithPhone action{alternateOption currentOption}}"
